exploreGraphLists.query:
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX shui: <https://vocab.eccenca.com/shui/>
PREFIX di: <https://vocab.eccenca.com/di/>
SELECT DISTINCT ?graph WHERE {
  { GRAPH ?graph { ?graph shui:isSystemResource true . } }
  UNION
  { GRAPH ?graph { ?graph a shui:ShapeCatalog . } }
  UNION
  { GRAPH ?graph { ?graph a shui:QueryCatalog . } }
}

SELECT DISTINCT ?graph WHERE {
  GRAPH ?graph { ?graph a ?type .
  FILTER NOT EXISTS {?graph <https://vocab.eccenca.com/shui/isSystemResource> true.}
  VALUES ?type { <http://www.w3.org/2002/07/owl#Ontology> }
  }
}

exploreModuleConfiguration.navigationTopQuery:
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX shui: <https://vocab.eccenca.com/shui/>
SELECT DISTINCT ?resource ?hasChildren
{{FROM}}
WHERE {
  {
    { SELECT DISTINCT ?resource { [] a ?resource . } }
    FILTER NOT EXISTS { ?resource rdfs:subClassOf [] }
  } UNION {
    ?resource a owl:Class .
    FILTER NOT EXISTS { ?resource rdfs:subClassOf [] }
  } UNION {
    ?resource a rdfs:Class .
    FILTER NOT EXISTS { ?resource rdfs:subClassOf [] }
  } UNION {
    ?graph shui:managedClasses ?resource .
    FILTER NOT EXISTS { [] owl:imports ?graph }
  }
  FILTER(isIRI(?resource))
  BIND( IF( EXISTS{ [] rdfs:subClassOf ?resource }, "hasChildren", "noChildren") as ?hasChildren )
} ORDER BY ?resource

exploreModuleConfiguration.navigationSubQuery:
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
      PREFIX owl: <http://www.w3.org/2002/07/owl#>

      SELECT ?resource ?hasChildren
      {{FROM}}
      WHERE {
        ?resource rdfs:subClassOf {{RESOURCE}} .
        FILTER(isIRI(?resource)) .
        BIND(IF(EXISTS{ [] rdfs:subClassOf ?resource . }, "hasChildren", "noChildren") AS ?hasChildren)
      }

exploreModuleConfiguration.navigationSearchQuery:
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX shui: <https://vocab.eccenca.com/shui/>
PREFIX skos: <http://www.w3.org/2004/02/skos/core#>

SELECT DISTINCT ?resource ?hasChildren
{{FROM}}
WHERE {
  {
    ?resource rdfs:subClassOf [] .
  } UNION {
    { SELECT DISTINCT ?resource { [] a ?resource . } }
  } UNION {
    ?resource a owl:Class .
  } UNION {
    ?resource a rdfs:Class .
  } UNION { 
    ?graph shui:managedClasses  ?resource . 
    FILTER NOT EXISTS { [] owl:imports ?graph }
  }

  FILTER(isIRI(?resource)) .

  OPTIONAL { ?resource rdfs:label ?label1 . }
  OPTIONAL { ?resource skos:prefLabel ?label2 . }

  BIND( IF( EXISTS { [] rdfs:subClassOf ?resource }, "hasChildren", "noChildren") as ?hasChildren )

  FILTER(
    regex(str(?resource),"""{{QUERY}}""","i") ||
    regex(str(?label1),"""{{QUERY}}""","i") ||
    regex(str(?label2),"""{{QUERY}}""","i")
  )

}

exploreModuleConfiguration.navigationListQuery:
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
      SELECT ?instance
      {{FROM}}
      WHERE {
        {
          ?instance a {{RESOURCE}} .
          FILTER isIRI(?instance) .
        } UNION {
          ?class rdfs:subClassOf+ {{RESOURCE}} .
          ?instance a ?class .
          FILTER isIRI(?instance).
        }
      }

navigationConfiguration.topConceptQuery:
# Computes the root resources of the class hierarchy forest used for
# the navigation list.
#
# ?resource: root of a tree in the forest
#
# Note: SELECT must be exactly ?resource.
# No rebinding, aliases, or expressions allowed in the projection.
SELECT DISTINCT ?resource
WHERE {
  {
    {

      # Get classes that are used as the type of a resource
      SELECT DISTINCT ?resource
      WHERE {
        [] rdf:type ?resource .
      }
    }

    # Exclude classes with a non-trivial superclass
    FILTER NOT EXISTS {
      ?resource rdfs:subClassOf ?parentClass .
      FILTER (?parentClass != owl:Thing)
    }
  } UNION {

    # Get all owl:Class and rdfs:Class resources
    ?resource rdf:type ?classType .
    VALUES ?classType { owl:Class rdfs:Class }

    # Exclude classes with explicit or implicit non-trivial superclasses
    FILTER (
      NOT EXISTS {

        # Explicitly defined non-trivial superclass
        ?resource rdfs:subClassOf ?explicitParentClass .
        FILTER (?explicitParentClass != owl:Thing)
      } && NOT EXISTS {

        # Implicitly defined non-trivial superclass
        ?resource owl:equivalentClass | rdfs:subClassOf ?complexClass .
        ?complexClass owl:intersectionOf ?classExpression .
        ?classExpression rdf:rest*/rdf:first ?implicitParentClass .
        FILTER isIRI(?implicitParentClass)
      }
    )
  } UNION {

    # Get classes managed by a graph in the current context
    ?graph shui:managedClasses ?resource .

    # Exclude managed classes of imported graphs
    FILTER NOT EXISTS { [] owl:imports+ ?graph }

    # Exclude managed classes with a non-trivial managed superclass
    FILTER NOT EXISTS {
      ?resource rdfs:subClassOf ?parentClass .
      ?graph shui:managedClasses ?parentClass .
      FILTER (?parentClass != owl:Thing)
    }
  }

  # Exclude complex class expressions
  FILTER isIRI(?resource)

  # Placeholder for future use
  {{VALUES}}
}

facets.query:
# Changeset vocabulary prefix used by versioning graphs
PREFIX cs: <http://purl.org/vocab/changeset/schema#>

# Computes the latest change date facet for a triple and its annotations.
#
# ?subject: subject of the triple
# ?predicate: predicate of the triple
# ?object: object of the triple
# ?lastChangeDate: latest change date of the triple
#
# Note: SELECT must be exactly ?subject, ?predicate, ?object, and ?lastChangeDate.
# No rebinding, aliases, or expressions allowed in the projection.
SELECT ?subject ?predicate ?object (MAX(?changeDate) AS ?lastChangeDate)
WHERE {

  # Get each changeset and the corresponding triple change date
  ?changeSet a cs:ChangeSet ;
    cs:addition ?statement ;
    cs:createdDate ?changeDate .

  # Get the triple components
  ?statement a rdf:Statement ;
    rdf:subject ?subject ;
    rdf:predicate ?predicate ;
    rdf:object ?object .

  # Restrict bindings to context-relevant resources
  {{VALUES}}

# Get the latest change date for each triple
} GROUP BY ?subject ?predicate ?object
